cat > src/main/java/GameOfLife.java <<'EOF'
import java.util.Set;
import java.util.stream.Collectors;

public class GameOfLife {

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        return livingCells.stream()
                .filter(cell -> survives(cell, livingCells))
                .collect(Collectors.toUnmodifiableSet());
    }

    private boolean survives(Cell cell, Set<Cell> livingCells) {
        long livingNeighbours =
                livingCells.stream().filter(other -> isNeighbour(cell, other)).count();
        return livingNeighbours == 2 || livingNeighbours == 3;
    }

    private boolean isNeighbour(Cell cell, Cell other) {
        return !cell.equals(other)
                && Math.abs(cell.x() - other.x()) <= 1
                && Math.abs(cell.y() - other.y()) <= 1;
    }
}
EOF
