import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.IOException;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.Set;

public final class GameOfLifeCli {

    private static final ObjectMapper JSON = new ObjectMapper();

    private GameOfLifeCli() {}

    public static void main(String[] args) throws IOException {
        JsonNode request = JSON.readTree(System.in);
        Set<Cell> livingCells = readLivingCells(request.get("aliveCells"));
        Set<Cell> result = new GameOfLife().nextGeneration(livingCells);
        System.out.print(JSON.writeValueAsString(writeLivingCells(result)));
    }

    private static Set<Cell> readLivingCells(JsonNode aliveCells) {
        Set<Cell> livingCells = new LinkedHashSet<>();
        for (JsonNode cell : aliveCells) {
            livingCells.add(new Cell(cell.get(0).asInt(), cell.get(1).asInt()));
        }
        return livingCells;
    }

    private static ObjectNode writeLivingCells(Set<Cell> livingCells) {
        ArrayNode aliveCells = JSON.createArrayNode();
        livingCells.stream()
                .sorted(Comparator.comparingInt(Cell::x).thenComparingInt(Cell::y))
                .forEach(cell -> aliveCells.add(JSON.createArrayNode().add(cell.x()).add(cell.y())));
        return JSON.createObjectNode().set("aliveCells", aliveCells);
    }
}
EOF
